node - <<'JS'
const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1440, height: 960 }, deviceScaleFactor: 1 });
  await page.goto('http://127.0.0.1:4177/tuyen-dung.html', { waitUntil: 'domcontentloaded' });
  await page.waitForSelector('.jobs-list-hero-refresh');
  const metrics = await page.evaluate(() => {
    const hero = document.querySelector('.jobs-list-hero-refresh');
    const card = document.querySelector('.jobs-list-hero-card');
    const pills = Array.from(document.querySelectorAll('.jobs-list-hero-pills span')).map(el => el.textContent.trim());
    const h1 = document.querySelector('.jobs-list-hero-head h1');
    const r = hero.getBoundingClientRect();
    const cr = card.getBoundingClientRect();
    return {
      title: h1 && h1.textContent.trim(),
      heroHeight: Math.round(r.height),
      cardVisible: !!card && cr.width > 200 && cr.height > 100,
      pills,
      cssCache: document.querySelector('link[href*="jobs.css"]')?.getAttribute('href') || '',
      bodyClasses: document.body.className
    };
  });
  await page.screenshot({ path: '.m/tuyen-dung-hero-refresh.png', fullPage: false });
  await browser.close();
  console.log(JSON.stringify({ ok: true, screenshot: '.m/tuyen-dung-hero-refresh.png', metrics }, null, 2));
})();
